import React, { useState, useEffect } from 'react';
import TodoList from './components/TodoList';
import TodoForm from './components/TodoForm';
import SearchBar from './components/SearchBar';
import './App.css';

const App = () => {
    const [todos, setTodos] = useState(() => {
        const savedTodos = localStorage.getItem('todos');
        return savedTodos ? JSON.parse(savedTodos) : [];
    });
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        localStorage.setItem('todos', JSON.stringify(todos));
    }, [todos]);

    const addTodo = (text) => {
        const newTodo = {
            id: Date.now(),
            text: text,
            completed: false
        };
        setTodos([...todos, newTodo]);
    };

    const toggleTodo = (id) => {
        setTodos(todos.map(todo => 
            todo.id === id ? { ...todo, completed: !todo.completed } : todo
        ));
    };

    const editTodo = (id, newText) => {
        setTodos(todos.map(todo => 
            todo.id === id ? { ...todo, text: newText } : todo
        ));
    };

    const deleteTodo = (id) => {
        setTodos(todos.filter(todo => todo.id !== id));
    };

    const filteredTodos = todos.filter(todo => 
        todo.text.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="container py-5">
            <div className="row justify-content-center">
                <div className="col-lg-8">
                    <div className="card shadow-lg border-0">
                        <div className="card-header bg-primary text-white text-center py-4">
                            <h1 className="mb-0"><i className="bi bi-check2-square me-2"></i>투두리스트</h1>
                        </div>
                        <div className="card-body p-4">
                            <SearchBar searchQuery={searchQuery} setSearchQuery={setSearchQuery} />
                            <TodoForm addTodo={addTodo} />
                            <TodoList 
                                todos={filteredTodos} 
                                toggleTodo={toggleTodo}
                                editTodo={editTodo} 
                                deleteTodo={deleteTodo} 
                            />
                        </div>
                        <div className="card-footer bg-light text-center py-3">
                            <div className="d-flex justify-content-around">
                                <span className="badge bg-info fs-6">
                                    <i className="bi bi-list-task me-1"></i>전체: {todos.length}
                                </span>
                                <span className="badge bg-success fs-6">
                                    <i className="bi bi-check-circle me-1"></i>완료: {todos.filter(t => t.completed).length}
                                </span>
                                <span className="badge bg-warning fs-6">
                                    <i className="bi bi-clock me-1"></i>남음: {todos.filter(t => !t.completed).length}
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default App;
